import{_ as e,o as a,c as d,a1 as o}from"./chunks/framework.DceXOx8u.js";const m=JSON.parse('{"title":"Examples","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/examples/"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/examples/"}]]},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md"}'),r={name:"examples/index.md"};function s(n,t,i,c,h,l){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>Complete bots you can copy, run and adapt. Most examples are one <code>bot.js</code> file that shows a set of botmesh features, with a transcript captured from a real run and links to the guide of every feature it uses. A test runs every example&#39;s code and checks its transcript, so what you read is what you get.</p><h2 id="run-any-example" tabindex="-1">Run any example <a class="header-anchor" href="#run-any-example" aria-label="Permalink to &quot;Run any example&quot;">​</a></h2><ol><li><p>Set up a project once, as in <a href="/botmesh/guide/getting-started#requirements">Getting started</a> (Node.js 22.12+, <code>&quot;type&quot;: &quot;module&quot;</code>, <code>npm install @botmesh/core @botmesh/baileys</code>).</p></li><li><p>Save the example&#39;s code as <code>bot.js</code>.</p></li><li><p>Chat with it in the terminal, no phone needed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> botmesh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bot.js</span></span></code></pre></div></li><li><p>Connect it for real with <code>node bot.js</code> (a QR code for WhatsApp), or swap the provider for <a href="/botmesh/guide/getting-started#or-connect-telegram">Telegram</a>. The bot code does not change between channels.</p></li></ol><h2 id="beginner" tabindex="-1">Beginner <a class="header-anchor" href="#beginner" aria-label="Permalink to &quot;Beginner&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Level</th><th>Tags</th><th>Features</th><th>What you&#39;ll build</th></tr></thead><tbody><tr><td><a href="./greeting-bot">Greeting bot</a></td><td>Beginner</td><td>Commands</td><td><code>WELCOME</code>, text and regex triggers, <code>ctx.pass()</code>, slash commands, catch-all</td><td>A bot that welcomes each user once, says hello, echoes and lists its commands</td></tr><tr><td><a href="./faq-bot">FAQ bot</a></td><td>Beginner</td><td>Triggers</td><td>Normalized matching, keyword lists, <code>contains</code>, regex, precedence</td><td>Keyword answers to frequent questions, with a fallback</td></tr><tr><td><a href="./messages">Send messages</a></td><td>Beginner</td><td>Triggers</td><td>Trigger forms, <code>ctx.quote()</code>, <code>ctx.react()</code>, sender info</td><td>Every way to answer a text message</td></tr><tr><td><a href="./menu-bot">Menu bot</a></td><td>Beginner</td><td>Flows, Buttons</td><td><code>flow().choose()</code>, <code>then</code> sub-flows, <code>bot.conversation()</code>, buttons per channel</td><td>A pizza-place menu that works on every channel</td></tr><tr><td><a href="./poll-bot">Poll bot</a></td><td>Beginner</td><td>Polls, Reactions</td><td><code>ctx.poll()</code>, <code>bot.on(&#39;poll&#39;)</code>, <code>bot.send()</code>, <code>ctx.react()</code></td><td>Native polls answered with the live tally</td></tr><tr><td><a href="./media">Media replies</a></td><td>Beginner</td><td>Media</td><td>Photo, file, video, voice, sticker, location, contact; <code>bot.onType()</code>, <code>loadMediaOf()</code></td><td>A bot that sends every media kind and reacts to images</td></tr><tr><td><a href="./reminders">Reminder bot</a></td><td>Beginner</td><td>Scheduler</td><td><code>bot.delay()</code>, <code>bot.schedule()</code> with time zone, <code>task.cancel()</code>, <code>bot.send()</code></td><td>One-off reminders and a daily tip at 9:00</td></tr><tr><td><a href="./registration-flow">Registration flow</a></td><td>Beginner</td><td>Flows, Forms</td><td><code>.ask()</code> with <code>validate</code>, <code>.do()</code>, <code>c.state</code>, <code>.timeout()</code>, <code>/cancel</code></td><td>A validated sign-up that saves the user</td></tr></tbody></table><h2 id="intermediate" tabindex="-1">Intermediate <a class="header-anchor" href="#intermediate" aria-label="Permalink to &quot;Intermediate&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Level</th><th>Tags</th><th>Features</th><th>What you&#39;ll build</th></tr></thead><tbody><tr><td><a href="./shopping-flow">Shopping flow</a></td><td>Intermediate</td><td>Flows</td><td><code>.choose()</code>, <code>then</code> sub-flows, <code>goto</code>, computed state, timeouts</td><td>A small shop with quantity, confirmation and address</td></tr><tr><td><a href="./support-flow">Support with timeout</a></td><td>Intermediate</td><td>Conversations</td><td><code>bot.conversation()</code>, <code>c.waitText()</code>, <code>c.choose()</code>, <code>ConversationTimeout</code>, <code>ConversationCancelled</code></td><td>A support desk that opens tickets and handles abandoned sessions</td></tr><tr><td><a href="./rate-limiter">Plugin: rate limiter</a></td><td>Intermediate</td><td>Plugins, Hooks</td><td><code>definePlugin()</code>, <code>before(&#39;message&#39;)</code>, <code>abort()</code>, <code>onDispose()</code></td><td>A reusable plugin that limits messages per user</td></tr><tr><td><a href="./appointment-booking">Appointment booking</a></td><td>Intermediate</td><td>WhatsApp, Forms, SQLite</td><td><code>.persistent()</code>, <code>.form()</code>, <code>validate</code> + <code>maxAttempts</code>, <code>SQLiteStore</code>, <code>ctx.user</code></td><td>A booking flow that validates, confirms and resumes after a restart</td></tr><tr><td><a href="./order-tracking">Order tracking</a></td><td>Intermediate</td><td>WhatsApp, User data</td><td><code>ctx.user</code> namespaces, <code>bot.conversation()</code>, <code>MemoryStore</code> file</td><td>Order lookups that remember what each user follows</td></tr><tr><td><a href="./human-handoff">Human handoff</a></td><td>Intermediate</td><td>WhatsApp, Support</td><td><code>ctx.handoff()</code>, <code>bot.resume()</code>, handoff events, agent commands, <code>bot.delay()</code></td><td>A support bot that passes chats to agents and takes them back</td></tr><tr><td><a href="./multi-language">Multi-language bot</a></td><td>Intermediate</td><td>WhatsApp, Telegram, i18n</td><td><code>bot.locale()</code>, <code>ctx.t()</code>, <code>detect</code>, <code>ctx.setLang()</code>, plurals</td><td>A bot that answers each user in English or Spanish</td></tr><tr><td><a href="./group-bot">Group bot</a></td><td>Intermediate</td><td>WhatsApp, Telegram, Groups</td><td>per-participant conversations, <code>scope</code>, mentions, <code>groupMode</code>, admin-only commands</td><td>A group quiz with a scoreboard and admin commands</td></tr><tr><td><a href="./whatsapp-and-telegram">WhatsApp and Telegram at once</a></td><td>Intermediate</td><td>WhatsApp, Telegram, SQLite</td><td><code>defineBot</code>, two providers, store namespaces, stable ids</td><td>One bot file serving two channels from one process</td></tr></tbody></table><h2 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h2><p>They use <a href="/botmesh/guide/ai"><code>@botmesh/ai</code></a> with Anthropic by default; every page shows how to switch to OpenAI, Gemini or a local Ollama model. The API key always comes from an environment variable.</p><table tabindex="0"><thead><tr><th>Example</th><th>Level</th><th>Tags</th><th>Features</th><th>What it does</th></tr></thead><tbody><tr><td><a href="./ai-faq">AI FAQ assistant</a></td><td>Beginner</td><td>AI, Guardrails</td><td>autoresponder, persona, function triggers, <code>/reset</code></td><td>Answers shop questions with an LLM, declines anything off-topic and keeps fixed answers out of the model.</td></tr><tr><td><a href="./ai-tools-booking">AI booking assistant</a></td><td>Intermediate</td><td>AI, Tools</td><td>tool calling, <code>confirm: true</code>, <code>confirmLines</code>, <code>dedupe</code>, <code>enum</code></td><td>Books, lists and cancels appointments through your functions, with a confirmation before each change.</td></tr><tr><td><a href="./ai-rag">AI answers from your FAQ</a></td><td>Intermediate</td><td>AI, RAG</td><td><code>rag</code> retriever, <code>appendSources</code>, <code>warmup()</code></td><td>Answers from a Markdown FAQ, cites the section it used and admits what it does not know.</td></tr><tr><td><a href="./ai-streaming">Streaming AI replies</a></td><td>Intermediate</td><td>AI, Streaming, Telegram</td><td><code>stream</code>, drafts / edits / chunks, cost and latency settings</td><td>Shows the answer while the model writes it, tuned for cost and latency.</td></tr><tr><td><a href="./ai-router">AI router</a></td><td>Advanced</td><td>AI, Flows</td><td><code>generate()</code>, <code>replyInChat()</code>, flows, <code>bot.trigger()</code></td><td>Classifies free text with the model, runs payments as deterministic flows and leaves chit-chat to the AI.</td></tr><tr><td><a href="./ai-handoff">AI with human escalation</a></td><td>Advanced</td><td>AI, Tools, Handoff</td><td>tool calling, <code>ctx.handoff()</code>, <code>bot.resume()</code>, escape commands</td><td>Hands the chat to a person with a summary for the agent, then gets it back with <code>/bot</code>.</td></tr></tbody></table><h2 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Level</th><th>Tags</th><th>Features</th><th>What you build</th></tr></thead><tbody><tr><td><a href="./cloud-api-webhook">WhatsApp Cloud API webhook server</a></td><td>Advanced</td><td>WhatsApp, Cloud API, Webhooks, Security</td><td><code>@botmesh/meta</code> webhooks, raw-body signatures, 24-hour window, templates</td><td>A <code>node:http</code> server for the official Cloud API, with template fallback</td></tr><tr><td><a href="./production-bot">Production-ready bot</a></td><td>Advanced</td><td>Production, Docker, SQLite, Durability</td><td><code>SQLiteStore</code>, durability, persistent flows, health and metrics, graceful shutdown, logs</td><td>A support bot packaged as a small project with a Dockerfile</td></tr><tr><td><a href="./daily-digest">Scheduled daily digest</a></td><td>Advanced</td><td>Scheduler, Broadcast, Time zones</td><td>Durable scheduler, time zones, <code>bot.broadcast</code>, <code>ctx.user</code> opt-in/out</td><td>A digest at 08:00 in the bot&#39;s time zone, once per day across restarts</td></tr><tr><td><a href="./testing-your-bot">Testing your bot</a></td><td>Advanced</td><td>Testing, Vitest, Golden transcripts</td><td><code>createTestBot</code>, <code>expectReply</code>, golden transcripts, replay</td><td>A complete Vitest file that records and replays a conversation</td></tr><tr><td><a href="./faq-plugin">Build a plugin: FAQ with tools</a></td><td>Advanced</td><td>Plugins, Dependency injection</td><td><code>definePlugin</code>, <code>install</code>/<code>uninstall</code>, <code>ctx.onDispose</code>, <code>provide</code></td><td>A reusable FAQ plugin that shares its counters as a tool</td></tr></tbody></table><h2 id="feature-coverage" tabindex="-1">Feature coverage <a class="header-anchor" href="#feature-coverage" aria-label="Permalink to &quot;Feature coverage&quot;">​</a></h2><p>Which examples show each main feature. Every example also runs in the <a href="/botmesh/guide/dev-simulator">terminal simulator</a> and, except the Cloud API webhook server, on WhatsApp (Baileys) and Telegram with the same bot code.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Examples</th></tr></thead><tbody><tr><td>Flows (<code>flow()</code> DSL)</td><td><a href="./registration-flow">Registration flow</a>, <a href="./menu-bot">Menu bot</a>, <a href="./shopping-flow">Shopping flow</a>, <a href="./appointment-booking">Appointment booking</a>, <a href="./ai-router">AI router</a>, <a href="./testing-your-bot">Testing your bot</a>, <a href="./cloud-api-webhook">Cloud API webhook server</a></td></tr><tr><td>Questions, menus and forms (<code>ask</code>, <code>choose</code>, <code>form</code>)</td><td><a href="./registration-flow">Registration flow</a>, <a href="./menu-bot">Menu bot</a>, <a href="./shopping-flow">Shopping flow</a>, <a href="./support-flow">Support with timeout</a>, <a href="./appointment-booking">Appointment booking</a>, <a href="./order-tracking">Order tracking</a></td></tr><tr><td>Triggers and commands</td><td><a href="./greeting-bot">Greeting bot</a>, <a href="./faq-bot">FAQ bot</a>, <a href="./messages">Send messages</a>, <a href="./group-bot">Group bot</a>, <a href="./faq-plugin">FAQ plugin</a></td></tr><tr><td>Media (send and receive)</td><td><a href="./media">Media replies</a></td></tr><tr><td>Polls</td><td><a href="./poll-bot">Poll bot</a></td></tr><tr><td>Buttons</td><td><a href="./menu-bot">Menu bot</a>, <a href="./ai-tools-booking">AI booking assistant</a></td></tr><tr><td>Hooks</td><td><a href="./rate-limiter">Rate limiter</a>, <a href="./multi-language">Multi-language bot</a></td></tr><tr><td>Plugins</td><td><a href="./rate-limiter">Rate limiter</a>, <a href="./faq-plugin">FAQ plugin</a></td></tr><tr><td>i18n</td><td><a href="./multi-language">Multi-language bot</a></td></tr><tr><td>User data (<code>ctx.user</code>)</td><td><a href="./order-tracking">Order tracking</a>, <a href="./appointment-booking">Appointment booking</a>, <a href="./daily-digest">Daily digest</a>, <a href="./whatsapp-and-telegram">WhatsApp and Telegram</a></td></tr><tr><td>Human handoff</td><td><a href="./human-handoff">Human handoff</a>, <a href="./ai-handoff">AI with human escalation</a></td></tr><tr><td>Groups</td><td><a href="./group-bot">Group bot</a></td></tr><tr><td>Scheduler</td><td><a href="./reminders">Reminder bot</a>, <a href="./daily-digest">Daily digest</a>, <a href="./human-handoff">Human handoff</a></td></tr><tr><td>Broadcast</td><td><a href="./daily-digest">Daily digest</a></td></tr><tr><td>Stores</td><td><a href="./appointment-booking">Appointment booking</a>, <a href="./order-tracking">Order tracking</a>, <a href="./whatsapp-and-telegram">WhatsApp and Telegram</a>, <a href="./production-bot">Production-ready bot</a>, <a href="./daily-digest">Daily digest</a></td></tr><tr><td>Durability</td><td><a href="./production-bot">Production-ready bot</a></td></tr><tr><td>Multi-channel (one bot, several providers)</td><td><a href="./whatsapp-and-telegram">WhatsApp and Telegram</a></td></tr><tr><td>Webhooks and WhatsApp Cloud API</td><td><a href="./cloud-api-webhook">Cloud API webhook server</a></td></tr><tr><td>Telegram</td><td><a href="./whatsapp-and-telegram">WhatsApp and Telegram</a>, <a href="./ai-streaming">Streaming AI replies</a>, <a href="./group-bot">Group bot</a>, <a href="./multi-language">Multi-language bot</a></td></tr><tr><td>AI chat</td><td><a href="./ai-faq">AI FAQ assistant</a>, <a href="./ai-rag">AI answers from your FAQ</a>, <a href="./ai-router">AI router</a></td></tr><tr><td>AI tools with confirmation</td><td><a href="./ai-tools-booking">AI booking assistant</a>, <a href="./ai-handoff">AI with human escalation</a></td></tr><tr><td>AI chat history and RAG</td><td><a href="./ai-rag">AI answers from your FAQ</a>, <a href="./ai-faq">AI FAQ assistant</a>, <a href="./ai-router">AI router</a></td></tr><tr><td>AI streaming</td><td><a href="./ai-streaming">Streaming AI replies</a></td></tr><tr><td>Testing</td><td><a href="./testing-your-bot">Testing your bot</a>, <a href="./ai-streaming">Streaming AI replies</a></td></tr><tr><td>Terminal simulator (<code>npx botmesh dev</code>)</td><td><a href="./greeting-bot">Greeting bot</a>, <a href="./poll-bot">Poll bot</a>, <a href="./testing-your-bot">Testing your bot</a></td></tr></tbody></table><p>Apart from the Cloud API webhook server, the bot code of every example is the same on WhatsApp (Baileys) and Telegram: only the provider changes. Where a channel renders something differently (buttons, stickers), the example page says so, and the <a href="/botmesh/guide/channels#capability-matrix">capability matrix</a> lists the details.</p>',17)])])}const u=e(r,[["render",s]]);export{m as __pageData,u as default};
